    <div class="v2-grid-2"><label class="v2-field">ID sponsor *<input v-model.trim="draft.brandedGameConfigDraft.sponsor_id" placeholder="Es. partner-arena" required /></label><label class="v2-field">Nome sponsor *<input v-model.trim="draft.brandedGameConfigDraft.sponsor_name" placeholder="Nome mostrato ai tifosi" required /></label></div>
